Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Angle θ between r and F: <span id="thetaVal">90°</span>
  <input type="range" id="theta" min="10" max="170" step="5" value="90">
</label>
<div style="display:flex;flex-direction:column;gap:3px;">
  <span><b>View</b></span>
  <button id="vmGeo" class="active">Geometric construction</button>
  <button id="vmHand">Right-hand rule</button>
</div>
<div style="display:flex;flex-direction:column;gap:3px;">
  <span><b>Demo steps</b></span>
  <button id="step0">1 · Aligned force, weak torque</button>
  <button id="step1">2 · Perpendicular, max torque</button>
  <button id="step2">3 · Right-hand rule</button>
</div>
<div id="narration" style="font-size:11px;color:#333;max-width:260px;border-top:1px solid #ddd;padding-top:4px;">
  Drag the θ slider or orbit the scene. τ = r × F has magnitude rF·sinθ and points along +z here.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ELEMENT SPEC (fig coords: z-up; group g rotates fig->world with mapping (x,y,z)->(x,z,-y))
// axes x,y,z  -> thin black arrows (CylinderGeometry r=0.012 + Cone), +x lower-left, +y right, +z up
// O label     -> at origin; P -> black SphereGeometry(0.06) at tip of r
// r           -> thick blue (#1a3a6b) arrow O->P, P=(1.6,2.2,0)
// F           -> red (#cc2200) arrow from P, in z=0 plane, angle theta from r, len 1.4
// tau         -> orange (#ee7b0d) arrow from P along +z, len = 1.8*sin(theta)
// rExt        -> dashed black line P -> P+rHat*1.2
// fLine       -> dashed black line through P along fDir (line of action of F)
// r_perp      -> thin black segment O->foot (foot = perpendicular projection onto fLine) + right-angle square
// arc1/arc2   -> theta angle arcs at P (r vs F, and vertical-angle pair) as Line
// hand group  -> stylized palm (scaled sphere) + 4 finger capsules + thumb, mini r/F arrows, 2 curved torus curl arrows
const g = new THREE.Group();
g.rotation.x = -Math.PI / 2;
scene.add(g);
const W = (x, y, z) => new THREE.Vector3(x, z, -y);   // fig -> world (for labels)

const zHat = new THREE.Vector3(0, 0, 1);
const O = new THREE.Vector3(0, 0, 0);
const R = new THREE.Vector3(1.6, 2.2, 0);
const rHat = R.clone().normalize();
const rLen = R.length();
const FLEN = 1.4;
let theta = 90;

/* ── arrow factory (cylinder shaft + cone head, +y aligned) ── */
function makeArrow(color, rad, headLen, parent) {
  const grp = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color });
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad, 1, 12), mat);
  cyl.geometry.translate(0, 0.5, 0);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(rad * 2.6, headLen, 16), mat);
  cone.geometry.translate(0, headLen / 2, 0);
  grp.add(cyl, cone);
  (parent || g).add(grp);
  return {
    grp, mat,
    set(o, dir, len) {
      const L = Math.max(len, headLen + 0.02);
      grp.position.copy(o);
      grp.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
      cyl.scale.y = L - headLen;
      cone.position.y = L - headLen;
    }
  };
}

/* ── axes ── */
const axX = makeArrow(0x111111, 0.012, 0.12);
const axY = makeArrow(0x111111, 0.012, 0.12);
const axZ = makeArrow(0x111111, 0.012, 0.12);
axX.set(O, new THREE.Vector3(1, 0, 0), 3);
axY.set(O, new THREE.Vector3(0, 1, 0), 3);
axZ.set(O, new THREE.Vector3(0, 0, 1), 3);

/* ── main vectors ── */
const arrR = makeArrow(0x1a3a6b, 0.038, 0.24);
arrR.set(O, rHat, rLen);
const arrF = makeArrow(0xcc2200, 0.032, 0.2);
const arrTau = makeArrow(0xee7b0d, 0.032, 0.2);
const dotP = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
dotP.position.copy(R);
g.add(dotP);

/* ── dashed lines ── */
function makeDashed() {
  const m = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.09, gapSize: 0.06, transparent: true });
  const l = new THREE.Line(new THREE.BufferGeometry(), m);
  g.add(l);
  return {
    line: l, mat: m,
    set(a, b) {
      l.geometry.dispose();
      l.geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
      l.computeLineDistances();
    }
  };
}
const rExt = makeDashed();
const fLine = makeDashed();

/* ── r_perp segment + right-angle square ── */
const perpMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true });
const perpLine = new THREE.Line(new THREE.BufferGeometry(), perpMat);
const sqLine = new THREE.Line(new THREE.BufferGeometry(), perpMat);
g.add(perpLine, sqLine);

/* ── theta arcs ── */
const arcMat1 = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true });
const arcMat2 = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true });
function makeArc(mat) {
  const l = new THREE.Line(new THREE.BufferGeometry(), mat);
  g.add(l);
  return l;
}
const arc1 = makeArc(arcMat1);
const arc2 = makeArc(arcMat2);
function setArc(line, center, a0, a1, rad) {
  const pts = [];
  const n = 32;
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n);
    pts.push(new THREE.Vector3(center.x + rad * Math.cos(a), center.y + rad * Math.sin(a), center.z));
  }
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}

/* ── stylized right hand (lower-left) ── */
const hand = new THREE.Group();
const skin = new THREE.MeshBasicMaterial({ color: 0xf0c290 });
const palm = new THREE.Mesh(new THREE.SphereGeometry(0.3, 20, 14), skin);
palm.scale.set(1.15, 0.85, 0.5);
hand.add(palm);
for (let i = 0; i < 4; i++) {
  const f = new THREE.Mesh(new THREE.CapsuleGeometry(0.05, 0.26, 4, 10), skin);
  f.position.set(-0.17 + i * 0.115, 0.33, 0.02 + i * 0.01);
  f.rotation.x = -0.5 - i * 0.12;         // progressive curl
  hand.add(f);
}
const thumb = new THREE.Mesh(new THREE.CapsuleGeometry(0.055, 0.24, 4, 10), skin);
thumb.position.set(0.33, 0.02, 0.06);
thumb.rotation.z = -1.0;
thumb.rotation.x = -0.3;
hand.add(thumb);
hand.position.set(2.0, -0.7, -1.1);
hand.rotation.set(0.35, 0.15, -0.45);
hand.visible = false;
g.add(hand);

/* ── mini r/F arrows + curl arrows for the hand view ── */
const handBase = new THREE.Vector3(2.0, -0.55, -1.0);
const miniR = makeArrow(0x1a3a6b, 0.035, 0.2, g);
const miniF = makeArrow(0xcc2200, 0.03, 0.18, g);
miniR.grp.visible = miniF.grp.visible = false;
const curlMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const curl1 = new THREE.Group();
const curl2 = new THREE.Group();
g.add(curl1, curl2);
curl1.visible = curl2.visible = false;
function setCurl(grp, center, aStart, arcLen, rad) {
  grp.clear();
  const tor = new THREE.Mesh(new THREE.TorusGeometry(rad, 0.02, 8, 32, Math.max(arcLen, 0.2)), curlMat);
  grp.add(tor);
  const aEnd = aStart + arcLen;
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.14, 10), curlMat);
  cone.position.set(rad * Math.cos(aEnd), rad * Math.sin(aEnd), 0);
  const tan = new THREE.Vector3(-Math.sin(aEnd), Math.cos(aEnd), 0);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  grp.add(cone);
  grp.position.copy(center);
  grp.rotation.z = aStart;
  grp.children.forEach(c => c.position.z += 0.001);
}

/* ── reactive update ── */
function update() {
  const th = THREE.MathUtils.degToRad(theta);
  const fDir = rHat.clone().applyAxisAngle(zHat, th);
  arrF.set(R, fDir, FLEN);
  arrTau.set(R, zHat, 1.8 * Math.sin(th));

  rExt.set(R, R.clone().addScaledVector(rHat, 1.2));
  fLine.set(R.clone().addScaledVector(fDir, -2.6), R.clone().addScaledVector(fDir, 1.6));

  // foot of perpendicular from O to F's line of action
  const t = -R.dot(fDir);
  const foot = R.clone().addScaledVector(fDir, t);
  perpLine.geometry.dispose();
  perpLine.geometry = new THREE.BufferGeometry().setFromPoints([O, foot]);
  const u = fDir.clone();
  const v = O.clone().sub(foot).normalize();
  const s = 0.13;
  const p0 = foot, p1 = foot.clone().addScaledVector(u, s),
    p2 = foot.clone().addScaledVector(u, s).addScaledVector(v, s),
    p3 = foot.clone().addScaledVector(v, s);
  sqLine.geometry.dispose();
  sqLine.geometry = new THREE.BufferGeometry().setFromPoints([p1, p2, p3]);

  const aR = Math.atan2(rHat.y, rHat.x);
  const aF = aR + th;
  setArc(arc1, R, aR, aF, 0.55);
  setArc(arc2, R, aR + Math.PI, aF + Math.PI, 0.55);

  // label anchors
  const m1 = (aR + aF) / 2, m2 = m1 + Math.PI;
  th1.pos.copy(W(R.x + 0.85 * Math.cos(m1), R.y + 0.85 * Math.sin(m1), 0));
  th2.pos.copy(W(R.x + 0.85 * Math.cos(m2), R.y + 0.85 * Math.sin(m2), 0));
  rperpLbl.pos.copy(W(foot.x * 0.5, foot.y * 0.5, 0.05));
  fLbl.pos.copy(W(R.x + fDir.x * (FLEN + 0.25), R.y + fDir.y * (FLEN + 0.25), 0));
  tauLbl.pos.copy(W(R.x, R.y, 1.8 * Math.sin(th) + 0.28));

  // hand-view mini arrows + curls
  miniF.set(handBase, fDir, 1.0);
  setCurl(curl1, handBase.clone().addScaledVector(rHat, 0.55), aR + th * 0.08, th * 0.84, 0.36);
  setCurl(curl2, handBase.clone().addScaledVector(rHat, 0.9), aR + Math.PI + th * 0.08, th * 0.84, 0.3);
}

/* ── camera (perspective, after geometry) ── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: -45,
  elevationDeg: 18,
  heightFraction: 0.62,
  target: [0.55, 0.25, -0.85]
});

/* ── labels ── */
addLabel('<i>x</i>', W(3.2, 0, 0), { fontSize: '15px', bold: true });
addLabel('<i>y</i>', W(0, 3.2, 0), { fontSize: '15px', bold: true });
addLabel('<i>z</i>', W(0, 0, 3.2), { fontSize: '15px', bold: true });
addLabel('O', W(-0.05, -0.12, 0.05), { fontSize: '14px', offset: [-8, 8] });
addLabel('<i>P</i>', W(R.x + 0.1, R.y - 0.15, 0), { fontSize: '14px', offset: [6, 12] });
addLabel('r&#8407;', W(R.x * 0.5, R.y * 0.5, 0.12), { fontSize: '16px', bold: true, color: '#1a3a6b', offset: [-12, -10] });
const fLbl = addLabel('F&#8407;', W(3, 2, 0), { fontSize: '16px', bold: true, color: '#cc2200' });
const tauLbl = addLabel('&tau;&#8407;', W(R.x, R.y, 2), { fontSize: '16px', bold: true, color: '#ee7b0d', offset: [10, 0] });
const rperpLbl = addLabel('r<sub>&perp;</sub>', W(0.5, 0.5, 0), { fontSize: '13px' });
const th1 = addLabel('&theta;', W(1, 1, 0), { fontSize: '14px', bold: true });
const th2 = addLabel('&theta;', W(1, 1, 0), { fontSize: '14px', bold: true });

/* ── interactivity ── */
registerInteractive(arrTau.grp, {
  title: 'Torque τ = r × F',
  body: '|τ| = rF·sinθ. The orange arrow always stands perpendicular to the r–F plane; here it lies along +z. Its length is maximal at θ = 90° and vanishes when F is parallel to r.'
});
registerInteractive(arrF.grp, {
  title: 'Applied force F',
  body: 'F acts at point P. Only the component perpendicular to r (F·sinθ) produces torque about O.'
});
registerInteractive(arrR.grp, {
  title: 'Position vector r',
  body: 'r runs from the pivot O to the application point P. The moment arm r⊥ = r·sinθ is the perpendicular distance from O to the line of action of F.'
});

/* ── UI wiring ── */
const slider = document.getElementById('theta');
const thetaVal = document.getElementById('thetaVal');
slider.addEventListener('input', () => {
  theta = +slider.value;
  thetaVal.textContent = theta + '°';
  update();
});

const btnGeo = document.getElementById('vmGeo');
const btnHand = document.getElementById('vmHand');
function setMode(mode) {
  const handMode = mode === 'hand';
  hand.visible = handMode;
  miniR.grp.visible = miniF.grp.visible = handMode;
  curl1.visible = curl2.visible = handMode;
  const dim = handMode ? 0.15 : 1;
  arcMat1.opacity = arcMat2.opacity = perpMat.opacity = dim;
  rExt.mat.opacity = fLine.mat.opacity = handMode ? 0.25 : 1;
  btnGeo.classList.toggle('active', !handMode);
  btnHand.classList.toggle('active', handMode);
  if (handMode) {
    miniR.set(handBase, rHat, 1.4);
    update();
  }
}
btnGeo.addEventListener('click', () => setMode('geo'));
btnHand.addEventListener('click', () => setMode('hand'));

/* ── demo steps ── */
const steps = [
